package io.heapy.kotdoc.ast

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.io.File
import kotlinx.serialization.json.Json
import org.junit.jupiter.api.DynamicTest
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.TestFactory
import kotlin.test.assertEquals

/** Ten original corpus families; counts of internal observations are kept separate
 * from the actual JUnit case count. No expectation is generated by Kotlin. */
class OriginalTypesDataTest {
    @TestFactory fun originalDataFamilies()=listOf(
        "Metadata","Demand","Finite","Custom","Support","Carrier","Numeric","Sharing","MetadataPartial","Cast"
    ).map {name->DynamicTest.dynamicTest("original Data $name") {
        if(name=="Metadata"||name=="Demand") {
            val output=ByteArrayOutputStream()
            val previous=System.out
            try {
                System.setOut(PrintStream(output,true,Charsets.UTF_8))
                invoke(name)
            } finally {System.setOut(previous)}
            val expected=DataProofFiles.lines(if(name=="Metadata")"metadata-native.jsonl"else"demand-native.jsonl").map(Json::parseToJsonElement)
            assertEquals(expected,output.toString(Charsets.UTF_8).lineSequence().filter(String::isNotBlank).map(Json::parseToJsonElement).toList())
        } else invoke(name)
    } }
    @Test fun originalSourceAndFixtureIntegrity() {
        val root=File(System.getProperty("kotdoc.root","."))
        val process=ProcessBuilder("python3","tools/haskell-types-data-reference/verify.py","--check-source").directory(root).redirectErrorStream(true).start()
        val output=process.inputStream.bufferedReader().readText()
        assertEquals(0,process.waitFor(),output)
    }
    private fun invoke(name:String) {
        try {Class.forName("io.heapy.kotdoc.ast.Data${name}ProofKt").getMethod("main").invoke(null)}
        catch(error:java.lang.reflect.InvocationTargetException){throw error.targetException}
    }
}
